//go:build ignore

#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>

struct {
    __uint(type, BPF_MAP_TYPE_REUSEPORT_SOCKARRAY);
    __uint(max_entries, 128);
    __type(key, __u32);
    __type(value, __u32);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_udp_targets SEC(".maps");

// EVOLVE-BLOCK-START

/*
 * Approach
 * --------
 * End-to-end p99 latency is dominated by queueing in each worker’s UDP
 * socket. Each worker is effectively an M/G/1 queue handling both short
 * GETs (~10 µs) and long SCANs (~2 ms). When GETs share a worker with
 * SCANs, they suffer head-of-line blocking behind the long SCANs.
 *
 * We cannot see per-socket backlog from BPF, but we *can* cheaply classify
 * requests by parsing the UDP payload, whose format is fixed:
 *
 *   "GET  key [reqID]"
 *   "SCAN start limit [reqID]"
 *
 * Previous iteration:
 *   - Correctly classified GET vs SCAN.
 *   - But used `reuse->hash % active` (without extra randomness) to pick a
 *     worker. With a single client socket, `reuse->hash` is effectively
 *     constant, so almost all traffic mapped to one worker, causing huge
 *     queueing and multi-second p99.
 *
 * This version keeps the SCAN/GET classification but fixes distribution:
 *
 * 1) Robust GET/SCAN classification
 *    - Scan up to the first 64 bytes of the payload for the tokens "GET"
 *      or "SCAN" using sk_reuseport_md->data/data_end with full bounds
 *      checks and an unrolled loop so it satisfies the verifier.
 *    - If we see "SCAN" -> treat as a slow request.
 *      If we see "GET" or nothing -> treat as fast/unknown.
 *
 * 2) Two disjoint worker pools
 *    Let `active` be the number of configured workers (1..128):
 *      - SCAN pool (slow):  roughly 1/3 of workers, in the tail.
 *      - GET pool  (fast):  remaining workers, at the front.
 *
 *    We always ensure:
 *      - At least 1 fast worker.
 *      - At least 1 slow worker (when active > 1).
 *
 *    Layout:
 *      [ fast_workers ... ][ scan_workers ... ]
 *
 *    Selection:
 *      - Draw per-packet randomness with bpf_get_prandom_u32().
 *      - Compute a randomized hash: h = reuse->hash ^ rnd.
 *      - If SCAN:
 *          slot = fast_workers + (h % scan_workers);
 *        Else (GET/unknown):
 *          slot = h % fast_workers;
 *
 *    This:
 *      - Restores good utilization and avoids hot-spotting even with a
 *        single client flow (because of per-packet randomness).
 *      - Insulates GETs from SCAN-induced head-of-line blocking by never
 *        sending GETs to the SCAN pool.
 *      - Spreads SCANs across a smaller subset, keeping their queues
 *        manageable while preserving overall throughput.
 *
 * 3) Verifier friendliness
 *    - Only existing maps are used: pebble_udp_targets and
 *      pebble_agent_state.
 *    - Only one call to bpf_sk_select_reuseport.
 *    - Bounded, fully unrolled scan loop and minimal stack usage.
 *    - Deterministic except for verifier-approved randomness from
 *      bpf_get_prandom_u32().
 */

struct agent_state {
    __u32 active;
    __u32 pad;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

/* Return 1 for SCAN, 0 for GET/unknown. */
static __always_inline int classify_scan(struct sk_reuseport_md *reuse)
{
    unsigned char *data = (unsigned char *)(long)reuse->data;
    unsigned char *data_end = (unsigned char *)(long)reuse->data_end;

    /* Need at least a few bytes to match tokens; otherwise treat as GET. */
    if (data + 4 > data_end)
        return 0;

    unsigned char *p = data;

#pragma unroll
    for (int i = 0; i < 64; i++) {
        /* Ensure we can safely read up to 4 bytes from p. */
        if (p + 4 > data_end)
            break;

        __u8 c0 = p[0];
        __u8 c1 = p[1];
        __u8 c2 = p[2];
        __u8 c3 = p[3];

        /* Detect "GET" fast-path: treat as non-scan. */
        if (c0 == 'G' && c1 == 'E' && c2 == 'T')
            return 0;

        /* Detect "SCAN" (uppercase as used by the client). */
        if (c0 == 'S' && c1 == 'C' && c2 == 'A' && c3 == 'N')
            return 1;

        p++;
    }

    /* Default: if we didn't find "SCAN", treat as GET/unknown. */
    return 0;
}

SEC("sk_reuseport/selector")
enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
{
    __u32 key = 0;
    struct agent_state *state = bpf_map_lookup_elem(&pebble_agent_state, &key);
    if (!state)
        return SK_PASS;

    __u32 active = state->active;
    if (active == 0)
        return SK_PASS;

    if (active > 128)
        active = 128;

    __u32 slot = 0;

    if (active == 1) {
        /* Only one worker; nothing to balance. */
        slot = 0;
    } else {
        int is_scan = classify_scan(reuse);

        /*
         * Partition workers into:
         *   [0 .. fast_workers-1]       : GET/fast pool
         *   [fast_workers .. active-1]  : SCAN/slow pool
         */
        __u32 scan_workers = active / 3;
        if (scan_workers == 0)
            scan_workers = 1;
        if (scan_workers >= active)
            scan_workers = active - 1;

        __u32 fast_workers = active - scan_workers; /* >= 1 */

        __u32 rnd = bpf_get_prandom_u32();
        __u32 h = reuse->hash ^ rnd;

        if (is_scan) {
            /* SCAN: route only within the tail SCAN pool. */
            __u32 idx = h % scan_workers;
            slot = fast_workers + idx;
        } else {
            /* GET/unknown: route only within the fast pool. */
            __u32 idx = h % fast_workers;
            slot = idx;
        }
    }

    /* Single reuseport selection; kernel ignores additional calls. */
    bpf_sk_select_reuseport(reuse, &pebble_udp_targets, &slot, 0);

    return SK_PASS;
}

// EVOLVE-BLOCK-END

char _license[] SEC("license") = "GPL";

generation_feedback:
- **Alignment with intent**

  - Logic-wise, this is much closer to the design goals:
    - You now classify GET vs SCAN in BPF.
    - You reintroduced per-packet randomness via `bpf_get_prandom_u32()`.
    - You split workers into a GET pool and a SCAN pool to avoid HoL blocking.
  - Behavior-wise, though, it still misses the primary goal at high load:
    - Overall p99 vs rate (ms): 50k: **1.55**, 60k: **2.06**, 80k: **1.98**, 100k: **2.08**, 140k: **22.25**.
    - Baseline agent was ≈**16 ms** at 140k; so you **regressed p99 at the highest load**, even though you fixed the multi-second blowup from the previous attempt.

- **Observed behavior / takeaways**

  - At ≤100k:
    - Overall p99 ≈2 ms, GET p99 ≈0.63–0.66 ms, SCAN p99 ≈5.4–5.7 ms.
    - This strongly suggests:
      - Classification is working (GETs much faster than SCANs).
      - Distribution within each pool is healthy (no obvious hotspot).
  - At 140k:
    - Overall p99 jumps to ~22 ms with zero stddev across iterations.
    - Given the workload (≈0.5% SCAN, 2 ms service, 6 workers):
      - Your config is: 4 fast (GET-only) workers, 2 slow (SCAN-only) workers.
      - Per SCAN worker: ~350 scans/s, 2 ms each → ρ ≈ 0.7. This is high enough to produce big tail queueing for SCANs.
      - GET pool is lightly loaded (ρ ≈ 0.35), so GET p99 is probably fine; the **overall p99 is likely dominated by SCANs in the overloaded 2-worker pool**.
    - Also, 2 of 6 workers are almost exclusively handling 0.5% of traffic, so you are underusing capacity, partially violating the “avoid idle workers” goal.

- **Top changes to try next**

  1. **Give SCANs more workers (reduce their utilization, shrink their tail).**

     - Right now:

       ```c
       __u32 scan_workers = active / 3;
       if (scan_workers == 0)
           scan_workers = 1;
       if (scan_workers >= active)
           scan_workers = active - 1;
       __u32 fast_workers = active - scan_workers;
       ```

     - Change to roughly **half the workers for SCAN** when there’s enough capacity:

       ```c
       __u32 scan_workers;

       if (active <= 3) {
           // With very few workers, keep just one SCAN worker.
           scan_workers = 1;
       } else {
           // For 4+ workers, dedicate about half to SCANs.
           scan_workers = active / 2;
       }

       if (scan_workers >= active)
           scan_workers = active - 1;

       __u32 fast_workers = active - scan_workers;
       ```

     - For the common 6-worker case:
       - You’ll get 3 SCAN workers and 3 GET workers.
       - Both pools now have utilization ≈0.46 instead of 0.35 (GET) and 0.7 (SCAN), which should **pull SCAN p99 (and thus overall p99) down** without reintroducing GET↔SCAN HoL.

  2. **Simplify the classifier to just inspect the first word.**

     - Your current `classify_scan` unrolls up to 64 bytes and scans for “GET”/“SCAN” anywhere; that’s more complex and heavier than you need, and increases verifier pressure.

     - The client always sends requests starting with `GET` or `SCAN`, so you can replace `classify_scan` with:

       ```c
       static __always_inline int classify_scan(struct sk_reuseport_md *reuse)
       {
           unsigned char *data = (unsigned char *)(long)reuse->data;
           unsigned char *data_end = (unsigned char *)(long)reuse->data_end;

           if (data + 4 > data_end)
               return 0;

           __u8 c0 = data[0];
           __u8 c1 = data[1];
           __u8 c2 = data[2];
           __u8 c3 = data[3];

           if (c0 == 'S' && c1 == 'C' && c2 == 'A' && c3 == 'N')
               return 1;   // SCAN

           // Treat everything else (including "GET") as non-scan.
           return 0;
       }
       ```

     - This keeps correctness for the known payload formats, shrinks the program, and removes any risk that the classifier itself is contributing to tail latency.

  3. **(If 1–2 still leave p99 high at 140k) Slightly bias SCAN distribution within their pool.**

     - Keep the same basic logic, but consider increasing randomness entropy (e.g., also mix in `reuse->len` or a shifted `reuse->hash`) if you see any per-worker imbalance in server logs.
     - This is a minor tweak compared to (1); first confirm whether just giving SCANs more workers is enough to pull overall p99 back below baseline.

